INSERT INTO "insights" ("insight_id", "display_order", "section", "topic", "severity", "title", "body", "metric_name", "metric_value", "caveat", "evidence_json") VALUES
('subcategory-negative-profit-tables', 1, 'products', 'negative_profit_subcategory', 'critical', 'Tables lost money overall', 'Tables (Furniture) recorded -$30 of profit on $300 of sales, a -10.0% margin, with 100.0% of its order lines at a loss. Profit was negative in 1 of 1 years. Its average line discount was 30.0%.', 'profit', -30.0, 'Totals cover the full period and every region. They show where losses were recorded, not their cause; losses may be concentrated in a few orders or discount levels.', '{"avg_discount": 0.3, "category": "Furniture", "loss_line_share": 1.0, "profit": -30.0, "profit_margin": -0.1, "sales": 300.0, "yearly_profit": {"2017": -30.0}}'),
('subcategory-negative-profit-art', 2, 'products', 'negative_profit_subcategory', 'critical', 'Art lost money overall', 'Art (Office Supplies) recorded -$5 of profit on $50 of sales, a -10.0% margin, with 100.0% of its order lines at a loss. Profit was negative in 1 of 1 years. Its average line discount was 20.0%.', 'profit', -5.0, 'Totals cover the full period and every region. They show where losses were recorded, not their cause; losses may be concentrated in a few orders or discount levels.', '{"avg_discount": 0.2, "category": "Office Supplies", "loss_line_share": 1.0, "profit": -5.0, "profit_margin": -0.1, "sales": 50.0, "yearly_profit": {"2016": -5.0}}'),
('region-lowest-margin-west', 3, 'drivers', 'regional_performance', 'warning', 'West has the lowest profit margin', 'West earned a -20.0% margin, 22.5 percentage points below the overall 2.5%. It accounts for 25.0% of sales but -200.0% of profit.', 'profit_margin', -0.2, 'Regional results combine differences in product mix, discount levels and customer segments. They describe what happened in the period, not why one region differs.', '{"overall_margin": 0.025, "regions": [{"profit": 60.0, "profit_margin": 0.1, "profit_share": 3.0, "region": "East", "sales": 600.0, "sales_share": 0.75}, {"profit": -40.0, "profit_margin": -0.2, "profit_share": -2.0, "region": "West", "sales": 200.0, "sales_share": 0.25}]}'),
('discount-profit-association', 4, 'drivers', 'discount_profit_pattern', 'warning', 'Margins are lower on heavily discounted lines', 'Order lines with discounts above 20% have a combined margin of -14.0%, against 38.0% for undiscounted lines. Across all lines, the rank correlation between discount and line margin is -0.95 (Spearman). The same direction appears within 1 of 1 categories with both undiscounted and heavily discounted lines.', 'spearman_discount_margin', -0.947368, 'This is an observed association, not a measured effect: discount levels also vary with product, region and order mix, so the data alone cannot show how profit would change if discounts changed. A controlled pricing test would be needed for that.', '{"bands": [{"discount_band": "No discount", "line_count": 2, "loss_line_share": 0.0, "profit": 95.0, "profit_margin": 0.38, "sales": 250.0}, {"discount_band": "1-20%", "line_count": 1, "loss_line_share": 1.0, "profit": -5.0, "profit_margin": -0.1, "sales": 50.0}, {"discount_band": "21-40%", "line_count": 1, "loss_line_share": 1.0, "profit": -30.0, "profit_margin": -0.1, "sales": 300.0}, {"discount_band": "Over 40%", "line_count": 1, "loss_line_share": 1.0, "profit": -40.0, "profit_margin": -0.2, "sales": 200.0}], "by_category": {"Furniture": {"high_discount_margin": -0.14, "no_discount_margin": 0.38}}, "high_discount_margin": -0.14, "no_discount_margin": 0.38, "spearman_rho": -0.947368, "threshold": 0.2}'),
('region-top-profit-east', 5, 'drivers', 'regional_performance', 'info', 'East contributes the most profit', 'East generated $60 of profit, 300.0% of the total, from 75.0% of sales, at a 10.0% margin (overall 2.5%).', 'profit', 60.0, 'Regional results combine differences in product mix, discount levels and customer segments. They describe what happened in the period, not why one region differs.', '{"overall_margin": 0.025, "regions": [{"profit": 60.0, "profit_margin": 0.1, "profit_share": 3.0, "region": "East", "sales": 600.0, "sales_share": 0.75}, {"profit": -40.0, "profit_margin": -0.2, "profit_share": -2.0, "region": "West", "sales": 200.0, "sales_share": 0.25}]}');
